  extensions: { vector }
});

await db.exec('CREATE EXTENSION IF NOT EXISTS vector;');
await db.exec(`
  CREATE TABLE IF NOT EXISTS notes (
    id SERIAL PRIMARY KEY,
    content TEXT,
    embedding vector(3)
  );
`);

